import json
import re
import os

from .alarms.data_collector import BscAlarmsCollector, BscAlarmsAttributesContainer
from .alarms.logger import log_alarms
from .alarms.utils import remove_alarms_not_in_time_frame, remove_matched_alarms
from .bsc.exception import NoMatchingAlarms
from .logger import LOGGER
from .utils import time_to_seconds


def dict_to_file(file_path, file_name, alarms_dict):
    """Write dictionary data to json file"""
    with open(os.path.join(file_path, file_name), 'w') as alarms_file:
        json.dump(alarms_dict, alarms_file, indent=4)


class Parser(object):
    """
    Parse BSC output and display messages according to expected results with provided
    logging level
    """

    def __init__(self, output_to_analyze):
        self.output = output_to_analyze

    def compare_trxs_status(self, expected_operational_state, expected_administrative_state, allow_negative_result):
        """
        Function to analyse TRXs operational and administrative status
        :param expected_operational_state: (string) operational state expected value
        :param expected_administrative_state: (string) operational state expected value
        :return: True if all states as expected False if not
        """
        all_states_as_expected = True
        trxs_status = re.findall(r'(TRX-\d+)\s+([\w-]+)\s+([\w-]+)', self.output)
        if not trxs_status:
            raise CannotReadDataFromOutput(self.output)
        for tx_stat in trxs_status:
            trx, administrative_state, operational_state = tx_stat[0], tx_stat[1], tx_stat[2]
            administrative_as_expected = self._states_comparator('administrative', trx, administrative_state,
                                                                 expected_administrative_state)
            operational_as_expected = self._states_comparator('operational', trx, operational_state,
                                                              expected_operational_state)
            if not administrative_as_expected or not operational_as_expected:
                all_states_as_expected = False
        if all_states_as_expected:
            return True
        else:
            if allow_negative_result:
                return False
            else:
                raise IncorrectTrxStates

    def compare_sectors_status(self, expected_operational_state, expected_administrative_state,
                               allow_negative_result=False):
        """
        Function to analyse sectors operational and administrative status
        :param expected_operational_state: (string) operational state expected value
        :param expected_administrative_state: (string) operational state expected value
        :param allow_negative_result: (boolean)
        :return: True if all states as expected False if not
        """
        all_states_as_expected = True
        sectors_status = re.findall(r'(\sBTS-\d+)\s+([\w-]+)\s+([\w-]+)', self.output)
        if not sectors_status:
            raise CannotReadDataFromOutput(self.output)
        for sts in sectors_status:
            sector, administrative_state, operational_state = sts
            administrative_as_expected = self._states_comparator('administrative', sector, administrative_state,
                                                                 expected_administrative_state)
            operational_as_expected = self._states_comparator('operational', sector, operational_state,
                                                              expected_operational_state)
            if not administrative_as_expected or not operational_as_expected:
                all_states_as_expected = False
        if all_states_as_expected:
            return True
        else:
            if allow_negative_result:
                return False
            else:
                raise IncorrectSectorsStates

    @staticmethod
    def _states_comparator(state_alias, bcf_obj, current, expected):
        if current == expected:
            LOGGER.debug('{} {}State: {}'.format(bcf_obj, state_alias, current))
        else:
            LOGGER.debug('{} has invalid {}State value: {} expected: {}'.format(bcf_obj, state_alias,
                                                                                current, expected))
            return False
        return True

    def analyze_bcf_active_alarms(self, expected_alarms=[], ignored_alarms=[], critical_alarms=[],
                                  path_to_file=False, bsc_name=None):
        """
        Function for bcf alarms analysis
        :param path_to_file: path to file where results from alarms analyzes should be write.
        :param expected_alarms: type: list - list with expected alarms
        :param ignored_alarms: type: list - list with ignored alarms
        :param critical_alarms: type: list - list with critical alarms (RFS specific)
        :return: expected, missing, unexpected, critical alarms list
        """
        expected, missing, unexpected, critical = [], [], [], []
        found_no_matching_alarms = self._verify_no_matching_alarms()
        if not found_no_matching_alarms:
            alarms_list = self.build_list_from_alarms_data(bsc_name)
            if ignored_alarms:
                alarms_list = remove_matched_alarms(alarms_list, ignored_alarms)[2]
            expected, missing, unexpected = remove_matched_alarms(alarms_list, expected_alarms)
            critical = remove_matched_alarms(alarms_list, critical_alarms)[0]
            self._log_all_alarms_data_dicts(expected, unexpected, missing, path_to_file)
        else:
            if expected_alarms:
                raise NoMatchingAlarms(
                    'Expected alarms {} cannot be found in bsc output: {}'.format(expected_alarms, self.output))
        return expected, missing, unexpected, critical

    def analyze_bcf_alarms_history(self, expected_alarms=[], ignored_alarms=[], critical_alarms=[],
                                   time_start=False, time_end=False, path_to_file=False, bsc_name=None):
        """
        Function for alarms history analysis
        :param expected_alarms: type: list - list with expected alarms
        :param ignored_alarms: type: list - list with ignored alarms
        :param critical_alarms: type: list - list with critical alarms (RFS specific)
        :param time_start: type: string %H:%M:%S - start timestamp from which alarms should be checked
        :param time_end: type: string %H:%M:%S - end timestamp for alarms checking
        :param path_to_file: type: string - path to crete files with found/unexpected/missing alarms data
        :return: True if all alarms are as expected, False or raise IncorrectAlarmsFound exception if some
        unexpected or missing alarms occurred
        """
        expected, missing, unexpected, critical = [], [], [], []
        found_no_matching_alarms = self._verify_no_matching_alarms()
        if not found_no_matching_alarms:
            alarms_list = self.build_list_from_alarms_data(bsc_name)
            if time_start and time_end:
                time_start = time_to_seconds(time_start)
                time_end = time_to_seconds(time_end)
                alarms_list = remove_alarms_not_in_time_frame(alarms_list, time_start, time_end)
            if ignored_alarms:
                alarms_list = remove_matched_alarms(alarms_list, ignored_alarms)[2]
            expected, missing, unexpected = remove_matched_alarms(alarms_list, expected_alarms)
            critical = remove_matched_alarms(alarms_list, critical_alarms)[0]
            self._log_all_alarms_data_dicts(expected, unexpected, missing, path_to_file)
        else:
            if expected_alarms:
                raise NoMatchingAlarms(
                    'Expected alarms {} cannot be found in bsc output: {}'.format(expected_alarms, self.output))
        return expected, missing, unexpected, critical

    def _verify_no_matching_alarms(self):
        """Check if alarms list is displayed after proper MML command in bsc output"""
        if "NO MATCHING ALARMS FOUND" in self.output:
            return True
        return False

    def _get_zeol_alarms_text_list(self, expected=True):
        alarms_list = re.findall(r'(?<=\)\s)(\d+)\s(.*)', self.output, re.IGNORECASE)
        if not alarms_list and expected:
            raise CannotReadDataFromOutput(self.output)
        return alarms_list

    def _log_all_alarms_data_lists(self, found, expected, ignored):
        self._log_list_of_existing_alarms('found', found, '')
        self._log_list_of_existing_alarms('ignored', ignored)
        self._log_list_of_existing_alarms('expected', expected)

    def _log_all_alarms_data_dicts(self, found, unexpected, missing, file_path):
        self._log_dict_of_existing_alarms('found expected', found, file_path)
        self._log_dict_of_existing_alarms('unexpected', unexpected, file_path)
        self._log_dict_of_existing_alarms('missing', missing, file_path)

    @staticmethod
    def _log_list_of_existing_alarms(alarms_def, alarms, separator=' '):
        """Log list of defined alarms if they exist and returns it"""
        if not alarms:
            LOGGER.debug('There\'s no {} alarms'.format(alarms_def))
        else:
            log_alarms('{} alarms:'.format(alarms_def.capitalize()), alarms, separator)

    @staticmethod
    def _log_dict_of_existing_alarms(alarms_def, alarms, file_path):
        """Log list of defined alarms if they exist and returns it"""
        if not alarms:
            LOGGER.debug('There\'s no {} alarms'.format(alarms_def))
        else:
            LOGGER.debug("{} alarms: {}".format(alarms_def, json.dumps(alarms), ))
            if file_path:
                dict_to_file(file_path, alarms_def, alarms)

    def build_list_from_alarms_data(self, bsc_name):
        alarms_list = []
        alarms = BscAlarmsCollector(self.output, bsc_name)
        for alarm in alarms:
            alarm = BscAlarmsAttributesContainer(alarm)
            alarm_dict = alarm.alarm_data_dict
            alarms_list.append(alarm_dict)
        return alarms_list


class IncorrectSectorsStates(Exception):
    """Raised if some sector have operational or administrative state different than expected"""
    def __init__(self):
        super(IncorrectSectorsStates, self).__init__('Not all sectors states are as expected')


class IncorrectTrxStates(Exception):
    """Raised if some TRX have operational or administrative state different than expected"""
    def __init__(self):
        super(IncorrectTrxStates, self).__init__('Not all TRX\'s states are as expected')


class CannotReadDataFromOutput(Exception):
    """Raised where desired data cannot be found in output given by user"""

    def __init__(self, output):
        super(CannotReadDataFromOutput, self).__init__("Expected data aren't present in output:{}".format(output))
